import{GARDEN_CONFIG as u}from"./config.min.js";import{seasonAt as d,wrapHour as p,clamp01 as c}from"./clock.min.js";export const STATES=["sunny","cloudy","windy","stormy"];export function weightsFor(t,n=u){return n.weather.weights[t]||n.weather.weights.summer}export function nextState(t,n,e,r=u){const o=weightsFor(n,r);let i=0;for(const a of STATES)a!==t&&(i+=o[a]||0);if(i<=0)return t;let s=0;const l=c(e)*i;for(const a of STATES)if(a!==t&&(s+=o[a]||0,l<=s))return a;return STATES[STATES.length-1]===t?STATES[0]:STATES[STATES.length-1]}export function dwellFor(t,n=u){const e=n.weather.dwell;return e.min+c(t)*(e.max-e.min)}export function temperatureAt(t,n=u){const e=n.weather.temperature,r=(Math.sin((p(t)-6)*Math.PI/12)+1)/2;return e.coldest+(e.warmest-e.coldest)*r}export function precipFor(t,n,e=u){if(t<=.01)return"none";const r=e.weather.temperature,o=temperatureAt(n,e);return o<r.snowBelow?"snow":o<r.sleetBelow?"sleet":"rain"}export function blendStates(t,n,e,r=u){const o=r.weather.states[t],i=r.weather.states[n],s=l=>o[l]+(i[l]-o[l])*c(e);return{gloom:s("gloom"),wind:s("wind"),rain:s("rain")}}export function createWeather(t="sunny"){return{state:t,from:t,transition:1,held:0,dwell:30,angle:.8,gloom:0,windStrength:0,rain:0,wind:{x:0,z:0},precip:"none"}}export function stepWeather(t,n,e,r=Math.random,o=!1,i=u){const s=i.weather,l=o?s.reducedTransitionSeconds:s.transitionSeconds;t.transition<1?t.transition=Math.min(1,t.transition+n/l):(t.held+=n,t.held>=t.dwell&&(t.from=t.state,t.state=nextState(t.state,d(e),r(),i),t.dwell=dwellFor(r(),i),t.held=0,t.transition=0));const a=blendStates(t.from,t.state,t.transition,i);return t.gloom=a.gloom,t.windStrength=a.wind,t.rain=a.rain,t.angle+=s.turnRate*n*(o?.4:1),t.wind.x=Math.cos(t.angle)*t.windStrength,t.wind.z=Math.sin(t.angle)*t.windStrength,t.precip=precipFor(t.rain,e,i),t}export function weatherWords(t){return t.precip==="snow"?"snow":t.precip==="sleet"?"sleet":t.precip==="rain"?"rain":t.state==="windy"||t.transition<.5&&t.from==="windy"?"windy":t.gloom>.35?"cloudy":"clear"}
